// 1. Use async/await syntax for asynchronous operations
// 2. Wrap in try-catch for error handling
// 3. Simulate API calls with Promises
// 4. Return appropriate data or error message

async function fetchUserData(userId) {
    try {
        const userResponse = await new Promise((resolve, reject) => {
            setTimeout(() => {
                if (userId === '123') {
                    resolve({ id: userId, name: 'John Doe' });
                } else {
                    reject(new Error('User not found'));
                }
            }, 100);
        });

        const postsResponse = await new Promise(resolve => {
            setTimeout(() => {
                resolve([{ id: 1, title: 'Post 1' }, { id: 2, title: 'Post 2' }]);
            }, 100);
        });

        return { user: userResponse, posts: postsResponse };
    } catch (error) {
        return { error: error.message };
    }
}

