// PSEUDO CODE:
// 1. Use an IIFE (Immediately Invoked Function Expression)
// 2. Define private variables and functions inside the IIFE
// 3. Return an object with public methods that can access private members
// 4. This creates encapsulation and data hiding

const Calculator = (function() {
    // Private variables
    let memory = 0;
    let history = [];

    // Private functions
    function validateNumber(num) {
        return typeof num === 'number' && !isNaN(num);
    }

    function addToHistory(operation, result) {
        history.push({ operation, result, timestamp: Date.now() });
    }

    // Public API
    return {
        add: function(a, b) {
            if (!validateNumber(a) || !validateNumber(b)) {
                throw new Error('Invalid numbers');
            }
            const result = a + b;
            addToHistory(`add(${a}, ${b})`, result);
            return result;
        },

        subtract: function(a, b) {
            if (!validateNumber(a) || !validateNumber(b)) {
                throw new Error('Invalid numbers');
            }
            const result = a - b;
            addToHistory(`subtract(${a}, ${b})`, result);
            return result;
        },

        getMemory: function() {
            return memory;
        },

        setMemory: function(value) {
            if (validateNumber(value)) {
                memory = value;
            }
        },

        getHistory: function() {
            return history.slice(); // Return a copy
        }
    };
})();

