// PSEUDO CODE:
// 1. Create an Iterator class that manages traversal state
// 2. Implement hasNext() to check if more elements exist
// 3. Implement next() to return current element and advance
// 4. Create a Collection class that can create iterators
// 5. The iterator provides a way to access elements sequentially

class Iterator {
    constructor(collection) {
        this.collection = collection;
        this.index = 0;
    }

    hasNext() {
        return this.index < this.collection.items.length;
    }

    next() {
        if (this.hasNext()) {
            return this.collection.items[this.index++];
        }
        throw new Error('No more elements');
    }

    reset() {
        this.index = 0;
    }
}

class Collection {
    constructor(items) {
        this.items = items;
    }

    createIterator() {
        return new Iterator(this);
    }

    forEach(callback) {
        const iterator = this.createIterator();
        while (iterator.hasNext()) {
            callback(iterator.next());
        }
    }
}

