// 1. Store the single instance in a static property
// 2. Check if instance exists in constructor
// 3. If exists, return it; otherwise create new instance
// 4. Initialize the instance only once
// 5. Provide methods to interact with the singleton

class DatabaseConnection {
    constructor() {
        if (DatabaseConnection.instance) {
            return DatabaseConnection.instance;
        }

        // Initialize the database connection
        this.connectionString = 'mongodb://localhost:27017/myapp';
        this.isConnected = false;
        this.connectionPool = [];

        DatabaseConnection.instance = this;
    }

    static getInstance() {
        if (!DatabaseConnection.instance) {
            DatabaseConnection.instance = new DatabaseConnection();
        }
        return DatabaseConnection.instance;
    }

    connect() {
        if (!this.isConnected) {
            this.isConnected = true;
            this.connectionPool.push('Connection established');
            return 'Connected to database';
        }
        return 'Already connected';
    }

    disconnect() {
        if (this.isConnected) {
            this.isConnected = false;
            this.connectionPool = [];
            return 'Disconnected from database';
        }
        return 'Not connected';
    }

    query(sql) {
        if (!this.isConnected) {
            throw new Error('Not connected to database');
        }
        return `Executed query: ${sql}`;
    }

    getStatus() {
        return {
            isConnected: this.isConnected,
            connectionString: this.connectionString,
            poolSize: this.connectionPool.length
        };
    }
}

