// 1. Use the Proxy constructor to create a proxy for an object
// 2. Define handler object with traps for get/set operations
// 3. Implement logging, validation, or other behaviors in traps
// 4. Return the proxy object that behaves like the original but with added functionality

function createReactiveObject(target) {
    const handler = {
        get: function(target, property, receiver) {
            console.log(`Getting property: ${property}`);
            return Reflect.get(target, property, receiver);
        },

        set: function(target, property, value, receiver) {
            console.log(`Setting property: ${property} = ${value}`);

            // Validation
            if (property === 'age' && (typeof value !== 'number' || value < 0)) {
                throw new Error('Age must be a positive number');
            }

            if (property === 'email' && !value.includes('@')) {
                throw new Error('Invalid email format');
            }

            return Reflect.set(target, property, value, receiver);
        },

        has: function(target, property) {
            console.log(`Checking if property exists: ${property}`);
            return Reflect.has(target, property);
        },

        deleteProperty: function(target, property) {
            console.log(`Deleting property: ${property}`);
            return Reflect.deleteProperty(target, property);
        }
    };

    return new Proxy(target, handler);
}

