// PSEUDO CODE:
// 1. Use function* syntax to create a generator function
// 2. Use yield keyword to pause and resume execution
// 3. Maintain state between yields using local variables
// 4. Return values one at a time when next() is called

function* fibonacciGenerator() {
    let a = 0;
    let b = 1;

    while (true) {
        yield a;
        [a, b] = [b, a + b];
    }
}

function* rangeGenerator(start, end, step = 1) {
    for (let i = start; i <= end; i += step) {
        yield i;
    }
}

function* primeGenerator() {
    yield 2;
    let num = 3;

    const isPrime = (n) => {
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) return false;
        }
        return true;
    };

    while (true) {
        if (isPrime(num)) {
            yield num;
        }
        num += 2;
    }
}

